USE clinica_sonrisa_feliz_v2;
CREATE TABLE IF NOT EXISTS empleados_nomina (id_empleado_nomina INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL UNIQUE,salario_base DECIMAL(10,2) NOT NULL,estado ENUM('activo','inactivo') DEFAULT 'activo',CONSTRAINT fk_nomina_usuario FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario));
CREATE TABLE IF NOT EXISTS pagos_nomina (id_pago_nomina INT AUTO_INCREMENT PRIMARY KEY,id_empleado_nomina INT NOT NULL,periodo CHAR(7) NOT NULL,monto DECIMAL(10,2) NOT NULL,metodo_pago ENUM('efectivo','tarjeta','transferencia','cheque') DEFAULT 'transferencia',estado_pago ENUM('pagado','pendiente','anulado') DEFAULT 'pendiente',fecha_pago DATE NULL,id_usuario_registra INT NULL,UNIQUE KEY uq_nomina_periodo(id_empleado_nomina,periodo),CONSTRAINT fk_pago_nomina_empleado FOREIGN KEY(id_empleado_nomina) REFERENCES empleados_nomina(id_empleado_nomina),CONSTRAINT fk_pago_nomina_usuario FOREIGN KEY(id_usuario_registra) REFERENCES usuarios(id_usuario));
INSERT INTO empleados_nomina(id_usuario,salario_base) SELECT id_usuario,CASE id_rol WHEN 1 THEN 1800 WHEN 2 THEN 1500 WHEN 3 THEN 850 WHEN 5 THEN 1200 ELSE 0 END FROM usuarios WHERE id_rol IN(1,2,3,5) ON DUPLICATE KEY UPDATE salario_base=VALUES(salario_base);
